size_t i, j;
adcs_mat3_t cct, ct;
double det, err;

if ((dcm == NULL) || (valid == NULL) || (determinant == NULL) ||
    (orthogonality_error == NULL)) {
    if (valid != NULL) {
        *valid = 0;
    }
    return ADCS_E_NULL;
}

*valid = 0;

if ((!isfinite(tolerance)) || (tolerance < 0.0)) {
    return ADCS_E_RANGE;
}

for (i = 0; i < 3U; i++) {
    for (j = 0; j < 3U; j++) {
        if (!isfinite(dcm->m[i][j])) {
            return ADCS_E_RANGE;
        }
    }
}

det = adcs_mat3_det(dcm);
*determinant = det;

if (det <= 0.0) {
    return ADCS_E_RANGE;
}

ct = adcs_mat3_transpose(dcm);
cct = adcs_mat3_mul(dcm, &ct);
err = adcs_mat3_frobenius_error_identity(&cct);
*orthogonality_error = err;

if (err > tolerance) {
    return ADCS_E_RANGE;
}

*valid = 1;
return ADCS_OK;

